CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,nickname TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',disabled INTEGER NOT NULL DEFAULT 0,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,user_id TEXT,kind TEXT NOT NULL,balance BIGINT NOT NULL CHECK(kind='system' OR balance>=0));
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,business_key TEXT UNIQUE NOT NULL,type TEXT NOT NULL,actor TEXT,reason TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS entries(id BIGSERIAL PRIMARY KEY,tx_id TEXT NOT NULL REFERENCES transactions(id),account_id TEXT NOT NULL REFERENCES accounts(id),amount BIGINT NOT NULL,balance_after BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history(id TEXT PRIMARY KEY,state TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS commands(user_id TEXT NOT NULL,request_id TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,actor TEXT,action TEXT NOT NULL,target TEXT,detail TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings VALUES('initial','10000') ON CONFLICT DO NOTHING;
INSERT INTO accounts VALUES('system',NULL,'system',0) ON CONFLICT DO NOTHING;
CREATE INDEX IF NOT EXISTS entries_account ON entries(account_id,id);
